import{_ as t,a,o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const d=JSON.parse('{"title":"AI Image Search","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/image-search.md","filePath":"generative-ai/image-search.md","lastUpdated":1789383332000}'),s={name:"generative-ai/image-search.md"};function i(n,e,h,c,p,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="ai-image-search" tabindex="-1">AI Image Search <a class="header-anchor" href="#ai-image-search" aria-label="Permalink to &quot;AI Image Search&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>Shoppers can search your catalog with a photo instead of words. A camera icon in the storefront search bar opens the file picker; the shopper picks a photo and the store searches for matching products.</p><p>With AI image search on, the model you chose describes what is in the photo, and the store searches for those keywords, so it recognizes far more kinds of products. With it off, the photo is still recognized, but by a simpler model that runs in the shopper&#39;s browser and knows fewer things.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>Image search has two switches: one that shows the camera icon, and one that hands the photo to the AI model.</p><ol><li>Go to <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>.</li><li>In the <strong>Settings</strong> section, switch <strong>Image Search Option</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong>. If your store has more than one channel, choose the channel at the top of the page.</li><li>In the <strong>AI Image Search</strong> section, switch <strong>Enabled</strong> on.</li><li>Choose the <strong>Model</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The Magic AI master switch and the provider key must be in place first; see <a href="./../configure/magic-ai.html">Generative AI Configuration</a>.</p><h2 id="what-the-shopper-sees" tabindex="-1">What the shopper sees <a class="header-anchor" href="#what-the-shopper-sees" aria-label="Permalink to &quot;What the shopper sees&quot;">​</a></h2><ol><li>The shopper clicks the camera icon in the search bar and chooses a photo. Only image files of up to 2 MB are accepted.</li><li>The photo is analyzed and the search results page opens with the products that match what was found in it.</li></ol><p>The photo is sent to the provider of the chosen model so it can be described. If your privacy policy lists the services that process visitor data, add the provider there.</p>',11)]))}const m=t(s,[["render",i]]);export{d as __pageData,m as default};
